-- Cash and bank accounts with an atomic ledger trigger
create table if not exists public.financial_accounts (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,account_type text not null check(account_type in ('cash','bank')),name text not null,currency_code text not null default 'GNF',opening_balance numeric(18,2) not null default 0 check(opening_balance>=0),current_balance numeric(18,2) not null default 0 check(current_balance>=0),is_active boolean not null default true,created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create unique index if not exists financial_accounts_tenant_name_idx on public.financial_accounts(tenant_id,lower(name));
create table if not exists public.financial_transactions (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,account_id uuid not null references public.financial_accounts(id),transaction_type text not null check(transaction_type in ('deposit','withdrawal')),amount numeric(18,2) not null check(amount>0),balance_after numeric(18,2) not null,reference text,description text,created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create index if not exists financial_transactions_tenant_date_idx on public.financial_transactions(tenant_id,created_at desc);
alter table public.financial_accounts enable row level security; alter table public.financial_transactions enable row level security;
drop policy if exists financial_accounts_read on public.financial_accounts; create policy financial_accounts_read on public.financial_accounts for select to authenticated using(tenant_id=(select public.current_tenant_id()));
drop policy if exists financial_accounts_insert on public.financial_accounts; create policy financial_accounts_insert on public.financial_accounts for insert to authenticated with check(tenant_id=(select public.current_tenant_id()) and created_by=(select auth.uid()) and public.has_tenant_role(array['owner','admin','manager','cashier','accountant']));
drop policy if exists financial_transactions_read on public.financial_transactions; create policy financial_transactions_read on public.financial_transactions for select to authenticated using(tenant_id=(select public.current_tenant_id()));
drop policy if exists financial_transactions_insert on public.financial_transactions; create policy financial_transactions_insert on public.financial_transactions for insert to authenticated with check(tenant_id=(select public.current_tenant_id()) and created_by=(select auth.uid()) and public.has_tenant_role(array['owner','admin','manager','cashier','accountant']));
grant select,insert on public.financial_accounts to authenticated; grant select,insert on public.financial_transactions to authenticated;
create or replace function public.apply_financial_transaction_balance() returns trigger language plpgsql security definer set search_path='' as $$ declare v_balance numeric(18,2); v_next numeric(18,2); v_tenant uuid; begin if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if; v_tenant:=public.current_tenant_id(); if v_tenant is null or new.tenant_id<>v_tenant or new.created_by<>auth.uid() then raise exception 'Tenant or creator mismatch' using errcode='42501'; end if; if not public.has_tenant_role(array['owner','admin','manager','cashier','accountant']) then raise exception 'Insufficient permission' using errcode='42501'; end if; select current_balance into v_balance from public.financial_accounts where id=new.account_id and tenant_id=v_tenant and is_active for update; if not found then raise exception 'Financial account not found or inactive'; end if; if new.amount is null or new.amount<=0 then raise exception 'Amount must be positive'; end if; v_next:=v_balance+case when new.transaction_type='deposit' then new.amount else -new.amount end; if v_next<0 then raise exception 'Insufficient account balance' using errcode='23514'; end if; update public.financial_accounts set current_balance=v_next where id=new.account_id and tenant_id=v_tenant; new.balance_after:=v_next; return new; end; $$;
revoke all on function public.apply_financial_transaction_balance() from public,anon,authenticated;
drop trigger if exists financial_transaction_apply_balance on public.financial_transactions; create trigger financial_transaction_apply_balance before insert on public.financial_transactions for each row execute function public.apply_financial_transaction_balance();
-- Remove an obsolete, superseded public RPC; transactions are now written through the RLS-protected ledger and internal trigger.
drop function if exists public.record_financial_transaction(uuid,text,numeric,text,text);
